def D(n):
    """Calculates the divisor n^3 + 4n^2 + 6n + 4."""
    return n**3 + 4*n**2 + 6*n + 4

def check_condition(n):
    """Checks if D(n) divides 20^(n+1)."""
    d_n = D(n)
    if d_n == 0:
        # This should not happen for non-negative n
        return False

    # Check if D(n) is 1. If D(n)=1, it always divides 20^(n+1).
    if d_n == 1:
        return True

    numerator = 20**(n + 1)

    if numerator % d_n == 0:
        return True
    else:
        return False

def get_prime_factors(num):
    """Returns a dictionary of prime factors and their exponents."""
    factors = {}
    d = 2
    temp = num
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

solutions = []
prime_factor_data = {}

print("--- Testing N = 0 to 15 ---")
for n in range(16):
    d_n = D(n)
    is_solution = check_condition(n)

    factors = get_prime_factors(d_n)
    prime_factor_data[n] = factors

    if is_solution:
        solutions.append(n)

    print(f"N={n}: D(n) = {d_n}. Divides 20^(n+1)? {'YES' if is_solution else 'NO'}. Factors: {factors}")

print("\n--- Results ---")
print(f"Solutions found: {solutions}")

def check_divisibility(n):
    # D(n) = n^3 + 4n^2 + 6n + 4
    D_n = n**3 + 4*n**2 + 6*n + 4
    # We check if D_n divides 20^(n+1)
    # We use integers to avoid floating point issues, though 20^(n+1) might grow fast.
    # Since we only check small values, standard Python integers should handle it.
    power_of_20 = 20**(n+1)

    if power_of_20 % D_n == 0:
        return True
    else:
        return False

# Check candidate solutions {0, 2, 6}
candidates = [0, 2, 6]
results = {}
for n in candidates:
    results[n] = check_divisibility(n)

print(f"Verification results for candidates {candidates}: {results}")

def is_2_5_smooth(k):
    if k <= 0:
        return False
    temp = k
    while temp % 2 == 0:
        temp //= 2
    while temp % 5 == 0:
        temp //= 5
    return temp == 1

solutions_m = []
# Searching up to m=50 based on the expectation that the set is small.
for m in range(1, 51):
    k = m*m + 1
    if is_2_5_smooth(k):
        solutions_m.append(m)

print(f"Solutions m found up to 50: {solutions_m}")

